-- IPMI V5 foundational schema. PostgreSQL 16+ target.
create extension if not exists pgcrypto;
create extension if not exists citext;
create table if not exists organisations (id uuid primary key default gen_random_uuid(), legal_name text not null, display_name text not null, status text not null default 'active' check (status in ('active','suspended','archived')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists users (id uuid primary key default gen_random_uuid(), email citext unique not null, password_hash text, status text not null default 'active' check (status in ('active','locked','disabled','pending')), mfa_enabled boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists programmes (id uuid primary key default gen_random_uuid(), code text unique not null, title text not null, category text not null, level text not null, status text not null default 'draft' check (status in ('draft','published','retired')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists applications (id uuid primary key default gen_random_uuid(), applicant_user_id uuid references users(id), programme_id uuid not null references programmes(id), status text not null default 'submitted' check (status in ('draft','submitted','under_review','accepted','rejected','withdrawn')), submitted_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists credentials (id uuid primary key default gen_random_uuid(), credential_id text unique not null, user_id uuid references users(id), programme_id uuid references programmes(id), status text not null check (status in ('active','expired','revoked','suspended')), issued_at timestamptz not null, expires_at timestamptz, revoked_at timestamptz, public_name text, verification_version integer not null default 1, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists audit_events (id uuid primary key default gen_random_uuid(), actor_user_id uuid references users(id), action text not null, resource_type text not null, resource_id text, ip_hash text, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index if not exists idx_credentials_credential_id on credentials(credential_id);
create index if not exists idx_audit_events_created_at on audit_events(created_at desc);
